// Écran d'accueil de l'app chauffeur Taxi Wal (v3) : logo, photo des 3 voitures et grands raccourcis.
// Ne bloque jamais un chauffeur : jamais par-dessus une alerte de course, jamais si l'URL ouvre une course.
(function () {
  try {
    var IMG = { me: "data:image/jpeg;base64,", tr: "data:image/jpeg;base64,", to: "data:image/jpeg;base64," };
    // ---------------------------------------------------------------------------------
    // Paramètres d'URL qui ouvrent une course précise : on ne montre JAMAIS l'accueil.
    // (lu tout de suite, avant que course-alerte.js ne nettoie l'URL)
    var URL_COURSE = /[?&](sonnerie|ca_demarrer|course|course_id|courseId|id_course)=/i.test(location.search || "");
    var DELAI_RETOUR = 5 * 60 * 1000; // 5 minutes ailleurs avant de remontrer l'accueil

    var X = '<svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true"><path d="M1 1l10 10M11 1L1 11" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/></svg>';
    var CSS = ""
      + "#tw-accueil-ch{position:fixed;inset:0;z-index:99998;background:linear-gradient(180deg,#0e2340,#081322);color:#fff;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;"
      + "display:flex;flex-direction:column;height:100vh;height:100dvh;overflow:hidden;touch-action:manipulation;-webkit-text-size-adjust:100%;"
      + "padding:calc(env(safe-area-inset-top) + 12px) 14px calc(env(safe-area-inset-bottom) + 12px);box-sizing:border-box;transition:opacity .25s}"
      + "#tw-accueil-ch *{box-sizing:border-box;touch-action:manipulation;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none}"
      + "#tw-accueil-ch .haut{display:flex;align-items:center;justify-content:space-between;gap:10px;flex:none}"
      + "#tw-accueil-ch .logo{font-weight:900;font-size:clamp(30px,9.5vw,42px);letter-spacing:1px;line-height:1;white-space:nowrap;color:#fff}#tw-accueil-ch .logo span{color:#22b35e}"
      + "#tw-accueil-ch .fermer{flex:none;width:auto!important;margin:0!important;display:flex;align-items:center;gap:6px;height:34px;padding:0 14px 0 12px;border-radius:999px;border:1px solid rgba(255,255,255,.28);background:rgba(255,255,255,.08);color:#fff;font-size:14px;font-weight:600;cursor:pointer}"
      + "#tw-accueil-ch .sous{flex:none;margin-top:6px;color:#b9c7dc;font-size:13px;letter-spacing:2.5px;text-transform:uppercase;font-weight:600}"
      + "#tw-accueil-ch .flotte{flex:none;margin-top:auto!important;display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:12px 0 10px;align-items:center}"
      + "#tw-accueil-ch .v{background:#fff;border-radius:12px;overflow:hidden;text-align:center;color:#0e1a2c;padding:4px 3px 6px;display:flex;flex-direction:column;justify-content:center;max-height:100%}"
      + "#tw-accueil-ch .v img{width:100%;height:clamp(62px,16vh,160px);min-height:0;object-fit:contain;display:block}"
      + "#tw-accueil-ch .v b{display:block;font-size:11.5px;line-height:1.15;margin-top:2px;flex:none}"
      + "#tw-accueil-ch .v{position:relative;border:3px solid transparent;cursor:pointer}#tw-accueil-ch .v:active{transform:scale(.97)}"
      + "#tw-accueil-ch .v.du-jour{border:4px solid #22b35e;box-shadow:0 0 0 2px #22b35e,0 4px 14px rgba(34,179,94,.45)}"
      + "#tw-accueil-ch .v.attenue{opacity:.6}"
      + "#tw-accueil-ch .v .pastille{display:block;flex:none;order:3;margin:4px 2px 0;white-space:normal;background:#22b35e;color:#fff;font-size:10px;font-weight:800;line-height:1.15;padding:3px 4px;border-radius:8px}"
      + "#tw-accueil-ch .bandeau-vdj{flex:none;margin-top:10px;background:#e7f5ec;color:#1f6b3f;border:2px solid #22b35e;border-radius:12px;padding:8px 10px;font-size:14px;font-weight:800;text-align:center}"
      + "#tw-accueil-ch .slogan{grid-column:1/-1;text-align:center;color:#b9c7dc;font-size:15px;font-weight:700;margin-top:6px}#tw-accueil-ch .grille{flex:none;display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}"
      + "#tw-accueil-ch .rc{width:auto!important;margin:0!important;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:clamp(84px,12.5vh,122px);padding:8px 6px;border-radius:16px;border:none;background:#178a46;box-shadow:0 4px 14px rgba(23,138,70,.35);color:#fff;font-weight:800;font-size:clamp(14.5px,4.2vw,17px);line-height:1.15;text-align:center;cursor:pointer}"
      + "#tw-accueil-ch .rc i{font-style:normal;font-size:clamp(24px,7vw,30px);line-height:1}"
      + "#tw-accueil-ch .rc.sec{background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.25);box-shadow:none}"
      + "#tw-accueil-ch .rc:active{transform:scale(.97)}"
      + "#tw-accueil-ch .continuer{flex:none;width:100%!important;margin:auto 0 0!important;background:transparent;border:none;color:#b9c7dc;font-size:15px;font-weight:700;padding:8px;cursor:pointer}"
      + "#tw-accueil-ch .connexion{flex:none;display:block;width:100%!important;margin:0!important;border:none;background:#178a46;box-shadow:0 4px 14px rgba(23,138,70,.45);color:#fff;font-weight:800;font-size:18px;border-radius:14px;padding:16px;cursor:pointer}"
      + "#tw-accueil-ch .aide{flex:none;text-align:center;color:#b9c7dc;font-size:14px;margin-top:12px}";

    // Raccourcis : chacun déclenche une action EXISTANTE de l'app (clic sur l'onglet / le lien existant).
    var RACCOURCIS = [
      { ic: "🚖", t: "Mes courses", onglet: "mes-courses" },
      { ic: "📢", t: "Demandes ouvertes", onglet: "demandes-ouvertes" },
      { ic: "📅", t: "Agenda", onglet: "agenda" },
      { ic: "📋", t: "Feuille de route", lien: "btn-feuille-route" },
      { ic: "💬", t: "Messages centrale", onglet: "messages" },
      { ic: "⛽", t: "J'ai fait le plein", onglet: "plein", sec: true }
    ];
    // Voitures des cartes : modèle → plaque (la feuille de route retrouve la voiture par sa plaque).
    var VOITURES = [{ cle: "me", nom: "Mercedes", plaque: "TXAW769" }, { cle: "tr", nom: "Renault Trafic", plaque: "TXAW084" }, { cle: "to", nom: "Toyota Corolla", plaque: "TXAQ203" }];
    function normPlaque(p) { return String(p || "").toUpperCase().replace(/[^A-Z0-9]/g, ""); }
    function dateLocale() { var d = new Date(); return d.getFullYear() + "-" + ("0" + (d.getMonth() + 1)).slice(-2) + "-" + ("0" + d.getDate()).slice(-2); }
    function lireJSON(k) { try { return JSON.parse(localStorage.getItem(k) || "null"); } catch (e) { return null; } }
    // Utilisateur connecté d'après la session Supabase gardée sur le téléphone (null si introuvable)
    function uidSession() {
      try {
        for (var i = 0; i < localStorage.length; i++) {
          var k = localStorage.key(i);
          if (/^sb-.*-auth-token$/.test(k)) { var x = lireJSON(k); var u = x && (x.user || (x.currentSession && x.currentSession.user)); if (u && u.id) return u.id; }
        }
      } catch (e) {}
      return null;
    }
    // Voiture du jour, en LECTURE SEULE, depuis ce que l'app a déjà gardé sur le téléphone (aucune requête ici) :
    //  - « taxiwal_vehicule_du_jour » : écrit par chauffeur.html (RPC mon_vehicule_du_jour, attribution centrale incluse)
    //    et par la feuille de route ;
    //  - « taxiwal_feuille_instantane » : dernière feuille ouverte (feuille de route).
    // Priorité : feuille ouverte du jour > attribution de la centrale. Au moindre doute → null (rien en évidence).
    // Renvoie { plaque, nom, source: "feuille" | "centrale", centrale: bool } ou null.
    function voitureDuJour() {
      try {
        var auj = dateLocale();
        var vdj = lireJSON("taxiwal_vehicule_du_jour");
        if (!vdj || vdj.date !== auj || !vdj.v || !vdj.v.vehicule_id || !vdj.v.plaque) return null;
        var uid = uidSession();
        if (uid && uid !== vdj.uid) return null;
        var centrale = vdj.v.choisi_par === "admin";
        var inst = lireJSON("taxiwal_feuille_instantane");
        var f = inst && inst.feuille;
        var feuilleOk = !!f && inst.uid === vdj.uid && f.date_service === auj
          && !f.verrouillee && !f.signee && !f.verifiee_admin && f.vehicule_id === vdj.v.vehicule_id;
        if (feuilleOk) return { plaque: normPlaque(vdj.v.plaque), plaqueAff: vdj.v.plaque, nom: vdj.v.nom, source: "feuille", centrale: centrale };
        if (centrale) return { plaque: normPlaque(vdj.v.plaque), plaqueAff: vdj.v.plaque, nom: vdj.v.nom, source: "centrale", centrale: true };
        return null;
      } catch (e) { return null; }
    }
    function nomCourt(nom) { var m = String(nom || "voiture").trim().split(/\s+/); return (m.length > 2 ? m.slice(0, 2) : m).join(" ").replace(/\s+classe$/i, ""); }
    function esc(t) { return String(t == null ? "" : t).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); }
    var voitureAffichee = null;   // voiture du jour retenue à l'affichage de l'accueil
    function boutonOnglet(nom) {
      try { return document.querySelector('nav.onglets button[data-onglet="' + nom + '"]'); } catch (e) { return null; }
    }
    function cible(r) {
      var el = r.onglet ? boutonOnglet(r.onglet) : document.getElementById(r.lien);
      if (!el) return null;
      try { if (getComputedStyle(el).display === "none") return null; } catch (e) {}
      return el;
    }

    // Attention : un élément en position:fixed (comme l'alerte de course) a offsetParent = null ; on teste donc display/visibility et la taille réelle.
    function visible(el) { try { if (!el || !el.isConnected) return false; var s = getComputedStyle(el); if (s.display === "none" || s.visibility === "hidden") return false; return el.getClientRects().length > 0; } catch (e) { return false; } }
    function alerteCourseOuverte() { return visible(document.getElementById("course-alerte-overlay")); }

    var surveillance = null;
    function fermer() {
      try { if (surveillance) { clearInterval(surveillance); surveillance = null; } } catch (e) {}
      try { var d = document.getElementById("tw-accueil-ch"); if (d) d.remove(); } catch (e) {}
      try { document.body.style.overflow = ""; } catch (e) {}
    }

    function bandeauVoiture(connecte) {
      try {
        if (!connecte) return "";
        var vj = voitureDuJour();
        if (!vj) return "";
        return '<div class="bandeau-vdj">' + (vj.centrale ? "🔑 " : "🚗 ") + "Aujourd'hui tu roules avec la " + esc(nomCourt(vj.nom)) + " (" + esc(vj.plaqueAff) + ")</div>";
      } catch (e) { return ""; }
    }
    function cartesVoitures(connecte) {
      var vj = null;
      if (connecte) { try { vj = voitureDuJour(); } catch (e) { vj = null; } }
      voitureAffichee = vj;
      var duJour = vj ? vj.plaque : null;
      var h = "";
      for (var i = 0; i < VOITURES.length; i++) {
        var v = VOITURES[i], estDuJour = !!duJour && normPlaque(v.plaque) === duJour;
        h += '<div class="v' + (estDuJour ? " du-jour" : (duJour ? " attenue" : "")) + '" data-plaque="' + v.plaque + '"'
          + (connecte ? ' role="button" tabindex="0" aria-label="Feuille de route avec la ' + v.nom + ' (' + v.plaque + ')"' : "") + '>'
          + (estDuJour ? '<span class="pastille">' + (vj.centrale ? "🔑 Attribuée par la centrale aujourd'hui" : "✓ Ta voiture aujourd'hui") + '</span>' : "")
          + '<img src="' + IMG[v.cle] + '" alt=""><b>' + v.nom + '</b></div>';
      }
      return h;
    }
    // Carte voiture touchée : ouvre la feuille de route avec cette voiture (la feuille décide : si une voiture
    // est déjà choisie aujourd'hui, elle ne change rien et affiche un message).
    function ouvrirFeuilleAvecVoiture(plaque) {
      try {
        var lien = document.getElementById("btn-feuille-route");
        var h = (lien && lien.getAttribute("href")) || "feuille-de-route.html";
        // Voiture attribuée par la centrale (et pas de feuille ouverte avec une autre) : on n'envoie JAMAIS de
        // voiture ; la feuille applique l'attribution comme aujourd'hui. Message si une autre voiture a été touchée.
        var vj = voitureAffichee;
        if (vj && vj.centrale) {
          if (plaque && normPlaque(plaque) !== vj.plaque) {
            try { sessionStorage.setItem("taxiwal_msg_accueil", JSON.stringify({ quand: Date.now(),
              texte: "La centrale t'a attribué la " + nomCourt(vj.nom) + " (" + vj.plaqueAff + ") aujourd'hui." })); } catch (e) {}
          }
          location.href = h; return;
        }
        if (!plaque) { location.href = h; return; }
        location.href = h + (h.indexOf("?") >= 0 ? "&" : "?") + "vehicule=" + encodeURIComponent(plaque);
      } catch (e) {}
    }
    function afficherEcran(connecte) {
      if (document.getElementById("tw-accueil-ch")) return;
      if (alerteCourseOuverte()) return;
      var st = document.getElementById("tw-accueil-ch-style");
      if (!st) { st = document.createElement("style"); st.id = "tw-accueil-ch-style"; st.textContent = CSS; document.head.appendChild(st); }
      var d = document.createElement("div");
      d.id = "tw-accueil-ch"; d.setAttribute("role", "dialog"); d.setAttribute("aria-modal", "true");
      var html = '<div class="haut"><span class="logo">TAXI <span>WAL</span></span>'
        + (connecte ? '<button type="button" class="fermer">' + X + 'Fermer</button>' : '') + '</div>'
        + '<div class="sous">Espace chauffeurs</div>'
        + bandeauVoiture(connecte)
        + '<div class="flotte">'
        + cartesVoitures(connecte)
        + '<div class="slogan">Bonne route ! 🚖</div></div>';
      var liste = [];
      if (connecte) {
        for (var i = 0; i < RACCOURCIS.length; i++) if (cible(RACCOURCIS[i])) liste.push(RACCOURCIS[i]);
        html += '<div class="grille">';
        for (var j = 0; j < liste.length; j++) {
          html += '<button type="button" class="rc' + (liste[j].sec ? ' sec' : '') + '" data-i="' + j + '"><i>' + liste[j].ic + '</i>' + liste[j].t + '</button>';
        }
        html += '</div><button type="button" class="continuer">Continuer vers l\'app →</button>';
      } else {
        html += '<button type="button" class="connexion">Se connecter</button><div class="aide">Un souci pour te connecter ? Appelle la centrale</div>';
      }
      d.innerHTML = html;
      document.body.appendChild(d);
      try { document.body.style.overflow = "hidden"; } catch (e) {}

      if (!connecte) {
        d.querySelector(".connexion").addEventListener("click", function () {
          fermer();
          var e = document.getElementById("email"); if (e) { try { e.focus(); } catch (x) {} }
        });
        surveillance = setInterval(function () {
          try { if (!visible(document.getElementById("ecran-login")) || alerteCourseOuverte()) fermer(); } catch (e) { fermer(); }
        }, 300);
        return;
      }

      // Connecté : reste ouvert jusqu'à un choix, MAIS se ferme immédiatement si une alerte de course apparaît.
      surveillance = setInterval(function () {
        try { if (alerteCourseOuverte()) fermer(); } catch (e) { fermer(); }
      }, 300);
      d.querySelector(".fermer").addEventListener("click", fermer);
      d.querySelector(".continuer").addEventListener("click", fermer);
      try {
        var cartes = d.querySelectorAll(".v[data-plaque]");
        for (var c = 0; c < cartes.length; c++) {
          cartes[c].addEventListener("click", function () { var pl = this.getAttribute("data-plaque"); fermer(); ouvrirFeuilleAvecVoiture(pl); });
        }
      } catch (e) {}
      var btns = d.querySelectorAll(".rc");
      for (var k = 0; k < btns.length; k++) {
        btns[k].addEventListener("click", function () {
          var r = liste[+this.getAttribute("data-i")];
          fermer();
          try {
            var el = r && cible(r);
            if (!el) return;
            if (r.lien) { var h = el.getAttribute("href"); if (h) location.href = h; else el.click(); return; }
            el.click();
            try { var nav = document.querySelector("nav.onglets"); if (nav) nav.scrollIntoView({ block: "start" }); } catch (e) {}
          } catch (e) {}
        });
      }
    }

    function afficher() {
      try {
        if (document.getElementById("tw-accueil-ch") || alerteCourseOuverte()) return;
        afficherEcran(!visible(document.getElementById("ecran-login")));
      } catch (e) { fermer(); }
    }

    // Une sonnerie de course envoyée par le service worker ferme l'accueil tout de suite.
    try {
      if (navigator.serviceWorker) navigator.serviceWorker.addEventListener("message", function (ev) {
        try { if (ev && ev.data && /sonner|course/i.test(String(ev.data.type || ""))) fermer(); } catch (e) {}
      });
    } catch (e) {}

    // Ouverture de l'app : on attend que l'app ait vérifié la session.
    function lancer() { if (URL_COURSE) return; setTimeout(afficher, 1800); }
    // Retour dans l'app après plus de 5 minutes ailleurs (pas à chaque petit retour).
    var cacheA = 0;
    document.addEventListener("visibilitychange", function () {
      try {
        if (document.hidden) { cacheA = Date.now(); return; }
        if (cacheA && Date.now() - cacheA > DELAI_RETOUR) { cacheA = 0; setTimeout(afficher, 600); }
      } catch (e) {}
    });
    if (document.readyState === "complete") lancer(); else window.addEventListener("load", lancer);
  } catch (e) { try { var d = document.getElementById("tw-accueil-ch"); if (d) d.remove(); } catch (x) {} }
})();
